import {persistStudyKey} from './persistence.js';
const key='english-os-foundations-a1a2';
const lessons=[
{title:'I am / You are',es:'Soy / Sos',goal:'Introduce yourself.',goalEs:'Aprender a presentarte.',why:'You need this structure to say who you are.',whyEs:'Es la base para hablar de vos mismo.',rule:'I am · You are · She is',ruleEs:'Con I usamos am; con you, are; con he/she, is.',example:'I am a student.',exampleEs:'Soy estudiante.',q:'Which sentence is correct?',qEs:'¿Cuál oración es correcta?',choices:['I is a student.','I am a student.','I are a student.'],answer:1,explain:'Use am after I.',explainEs:'Después de I usamos am.'},
{title:'I work / She works',es:'Trabajo / Ella trabaja',goal:'Talk about work and habits.',goalEs:'Hablar sobre trabajo y hábitos.',why:'Present simple helps you describe your day.',whyEs:'Vas a poder describir tu día.',rule:'I work → She works',ruleEs:'Con he/she, generalmente agregamos -s al verbo.',example:'She works in a bank.',exampleEs:'Ella trabaja en un banco.',q:'Choose the correct sentence.',qEs:'Elegí la oración correcta.',choices:['She work in a bank.','She working in a bank.','She works in a bank.'],answer:2,explain:'Present simple with she uses works.',explainEs:'Con she se escribe works.'},
{title:'I don’t work',es:'No trabajo',goal:'Make simple negative sentences.',goalEs:'Construir oraciones negativas.',why:'You can explain what you do not do.',whyEs:'Vas a explicar lo que no hacés.',rule:'I + do not (don’t) + verb',ruleEs:'Después de don’t usamos el verbo en su forma base.',example:'I don’t work on Sundays.',exampleEs:'No trabajo los domingos.',q:'Choose the correct negative sentence.',qEs:'Elegí la oración negativa correcta.',choices:['I don’t works on Sundays.','I don’t work on Sundays.','I no work on Sundays.'],answer:1,explain:'Use don’t + base verb: work.',explainEs:'Usá don’t + work, sin -s.'},
{title:'Do you work?',es:'¿Trabajás?',goal:'Ask yes/no questions.',goalEs:'Hacer preguntas de sí o no.',why:'Questions let you have real conversations.',whyEs:'Vas a poder conversar, no solo repetir frases.',rule:'Do + you + verb + ?',ruleEs:'Para preguntas en presente simple con you empezamos con Do.',example:'Do you work in finance?',exampleEs:'¿Trabajás en finanzas?',q:'Which question is correct?',qEs:'¿Qué pregunta es correcta?',choices:['Do you work in finance?','Does you work in finance?','You do work in finance?'],answer:0,explain:'Do you + base verb forms a question.',explainEs:'La estructura es Do + you + verbo base.'},
{title:'Words for work',es:'Vocabulario del trabajo',goal:'Recognize important work words.',goalEs:'Reconocer palabras laborales.',why:'Useful words make the next lessons easier.',whyEs:'Estas palabras te ayudan a entender el libro.',rule:'Bank · Office · Customer',ruleEs:'Banco · Oficina · Cliente',example:'A customer visits the bank.',exampleEs:'Un cliente visita el banco.',q:'What does “customer” mean?',qEs:'¿Qué significa customer?',choices:['Empleado','Cliente','Empresa'],answer:1,explain:'Customer means a person who buys something.',explainEs:'Customer significa cliente.'},
{title:'Listening basics',es:'Comprensión auditiva básica',goal:'Understand a short introduction.',goalEs:'Comprender una presentación corta.',why:'Listening first trains your ear.',whyEs:'Entrenás el oído antes de leer el texto.',rule:'Listen → Answer → Check',ruleEs:'Escuchá → Respondé → Comprobá',example:'I work in a bank.',exampleEs:'Trabajo en un banco.',audio:'Hello. My name is Anna. I work in a bank. I like my job.',q:'Where does Anna work?',qEs:'¿Dónde trabaja Anna?',choices:['At a hotel','In a bank','At a school'],answer:1,explain:'Anna says: I work in a bank.',explainEs:'Anna dice que trabaja en un banco.'},
{title:'Write about yourself',es:'Escribí sobre vos',goal:'Build two sentences yourself.',goalEs:'Crear dos oraciones por tu cuenta.',why:'Writing helps you remember structures actively.',whyEs:'Pasás de reconocer inglés a producirlo.',rule:'I am… / I work… / I like…',ruleEs:'Usá estas estructuras para empezar.',example:'I am a student. I work in a bank.',exampleEs:'Soy estudiante. Trabajo en un banco.',q:'Write two sentences about yourself.',qEs:'Escribí dos oraciones sobre vos.',kind:'write',sample:'I am a student. I work in finance.'}
];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const b=(en,es)=>'<span class="pair"><span>'+esc(en)+'</span><small>'+esc(es)+'</small></span>';
export const foundationTotal=()=>lessons.length;
export function foundationNext(){const i=lessons.findIndex((_,j)=>!getDone().includes(j));return i<0?null:{index:i,title:lessons[i].title,es:lessons[i].es}}
export function foundationCompleted(){try{return JSON.parse(localStorage.getItem(key)||'[]').filter(n=>Number.isInteger(n)&&n>=0&&n<lessons.length).length}catch{return 0}}
function getDone(){try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return []}}
function mark(i){const d=getDone();if(!d.includes(i))d.push(i);persistStudyKey(key,JSON.stringify(d))}
export function renderFoundation(shell,onDone,goCourse,requested){
let idx=Number.isInteger(requested)?requested:lessons.findIndex((x,i)=>!getDone().includes(i));if(idx<0)idx=0;
let e=lessons[idx],selection=null,readTranscript=false;let draftText='';try{draftText=JSON.parse(localStorage.getItem('english-os-foundation-drafts')||'{}')[idx]||''}catch{}
shell('<div class="foundation-view"><button class="back" id="foundation-back">← '+b('Back to course','Volver al curso')+'</button><div class="foundation-top">'+b('Foundations — A1 to A2','Preparación A1–A2')+'<span>'+b('Step '+(idx+1)+' of '+lessons.length,'Paso '+(idx+1)+' de '+lessons.length)+'</span></div><div class="foundation-meter"><span style="width:'+((idx+1)/lessons.length*100)+'%"></span></div><div class="eyebrow">LEARNING STEP · PASO DE APRENDIZAJE</div><h1 class="foundation-title">'+b(e.title,e.es)+'</h1><div class="foundation-panel"><div class="f-block"><span class="f-index">01</span><div><h2>'+b('What will you learn?','¿Qué vas a aprender?')+'</h2><p>'+b(e.goal,e.goalEs)+'</p><div class="f-why"><strong>'+b('Why is this useful?','¿Para qué sirve?')+'</strong><p>'+b(e.why,e.whyEs)+'</p></div></div></div><div class="f-block"><span class="f-index">02</span><div><h2>'+b('Look at the example','Mirá el ejemplo')+'</h2><div class="f-rule">'+b(e.rule,e.ruleEs)+'</div><div class="f-example">'+b(e.example,e.exampleEs)+'</div>'+(e.audio?'<button id="foundation-audio" class="f-outline">▶ '+b('Listen first','Primero escuchá')+'</button><button id="foundation-transcript" class="f-text">'+b('Show transcript (help)','Mostrar transcripción (ayuda)')+'</button><div id="foundation-audio-text" hidden>'+esc(e.audio)+'</div>':'')+'</div></div><div class="f-block"><span class="f-index">03</span><div><h2>'+b('Now it’s your turn','Ahora te toca a vos')+'</h2><p class="f-question">'+b(e.q,e.qEs)+'</p>'+(e.kind==='write'?'<textarea class="input" id="foundation-write" rows="4" placeholder="Write in English · Escribí en inglés">'+esc(draftText)+'</textarea>':'<div class="f-options">'+e.choices.map((o,j)=>'<button class="f-option" data-f-option="'+j+'"><span>'+String.fromCharCode(65+j)+'</span>'+esc(o)+'</button>').join('')+'</div>')+'<button id="foundation-check" class="f-submit">'+b(e.kind==='write'?'Save my writing':'Check my answer',e.kind==='write'?'Guardar mi texto':'Comprobar respuesta')+' →</button><div id="foundation-feedback" aria-live="polite"></div></div></div></div><div class="f-bottom">'+b('One short activity at a time. You can repeat any step.','Una actividad breve por vez. Podés repetir cualquier paso.')+'</div></div>');
document.querySelector('#foundation-back').onclick=goCourse;
document.querySelectorAll('[data-f-option]').forEach(btn=>btn.onclick=()=>{selection=Number(btn.dataset.fOption);document.querySelectorAll('[data-f-option]').forEach(x=>x.classList.toggle('selected',x===btn))});
document.querySelector('#foundation-audio')?.addEventListener('click',()=>{if(!('speechSynthesis' in window))return alert('Audio not available · Audio no disponible');speechSynthesis.cancel();const a=new SpeechSynthesisUtterance(e.audio);a.lang='en-GB';a.rate=.85;speechSynthesis.speak(a)});
document.querySelector('#foundation-transcript')?.addEventListener('click',()=>{readTranscript=true;document.querySelector('#foundation-audio-text').hidden=false});
if(e.kind==='write'){document.querySelector('#foundation-write').oninput=event=>{let all={};try{all=JSON.parse(localStorage.getItem('english-os-foundation-drafts')||'{}')}catch{}all[idx]=event.target.value;persistStudyKey('english-os-foundation-drafts',JSON.stringify(all))}};
document.querySelector('#foundation-check').onclick=()=>{
let correct=e.kind==='write'?(document.querySelector('#foundation-write').value.trim().length>=30):selection===e.answer;
const el=document.querySelector('#foundation-feedback');if(!correct){el.innerHTML='<div class="f-result retry">'+b('Try again.','Intentá de nuevo.')+'<p>'+b(e.kind==='write'?'Write at least two short sentences.':'Read the example and choose again.',e.kind==='write'?'Escribí por lo menos dos oraciones cortas.':'Volvé a mirar el ejemplo y elegí otra opción.')+'</p></div>';return}
mark(idx);if(e.kind==='write'){const draft=document.querySelector('#foundation-write').value.trim();persistStudyKey('english-os-foundation-writing',draft)}
el.innerHTML='<div class="f-result correct"><strong>'+b('Good work!','¡Bien hecho!')+'</strong><p>'+b(e.kind==='write'?'Your writing is saved, but has not been corrected automatically.':e.explain,e.kind==='write'?'Tu texto se guardó, pero todavía no fue corregido automáticamente.':e.explainEs)+'</p>'+(e.kind==='write'?'<p>'+b('Example: '+e.sample,'Ejemplo de referencia, no corrección.')+'</p>':'')+'</div><button id="foundation-next" class="f-submit">'+b(idx===lessons.length-1?'Go to Unit 01 — Brands':'Next lesson',idx===lessons.length-1?'Ir a la unidad 01 — Marcas':'Siguiente lección')+' →</button>';
document.querySelector('#foundation-next').onclick=()=>{if(idx<lessons.length-1)renderFoundation(shell,onDone,goCourse,idx+1);else onDone()};
};
}
